-- ADR-011 seed: Pokemon #1-#12, so the demo works on first start even if PokeAPI is slow or unreachable.
-- Catalogue columns are REAL PokeAPI data, generated by a script from responses captured on 2026-10-09
-- (no value typed by hand). Proprietary columns are DEMO values: localized_name = PokeAPI's Japanese (ja-hrkt)
-- name, region = Kanto, habitat = PokeAPI's species habitat, plus a few demo tags and notes.
-- A later sync of these ids refreshes the catalogue columns and keeps the proprietary ones (US03).

insert into pokemon (pokeapi_id, name, height_dm, weight_hg, sprite_url, image_url, category, types, abilities,
                     synced_at, localized_name, region, habitat, tags, notes, created_at, updated_at)
